import { FetchHttpHandler } from '@smithy/fetch-http-handler';
import { StsClient } from './StsClient';
import { Authentication } from './Authentication';
import { InternalLogger } from '../utils/InternalLogger';
export class BasicAuthentication extends Authentication {
    constructor(config, applicationId) {
        super(config, applicationId);
        /**
         * Provides credentials for an anonymous (guest) user. These credentials are retrieved from Cognito's basic
         * (classic) authflow.
         *
         * See https://docs.aws.amazon.com/cognito/latest/developerguide/authentication-flow.html
         *
         * Implements AwsCredentialIdentityProvider = Provider<AwsCredentialIdentity>
         */
        this.AnonymousCognitoCredentialsProvider = async () => {
            let retries = 1;
            while (true) {
                try {
                    const getIdResponse = await this.cognitoIdentityClient.getId({
                        IdentityPoolId: this.config.identityPoolId
                    });
                    const getOpenIdTokenResponse = await this.cognitoIdentityClient.getOpenIdToken(getIdResponse);
                    const credentials = await this.stsClient.assumeRoleWithWebIdentity({
                        RoleArn: this.config.guestRoleArn,
                        RoleSessionName: 'cwr',
                        WebIdentityToken: getOpenIdTokenResponse.Token
                    });
                    this.credentials = credentials;
                    try {
                        localStorage.setItem(this.credentialStorageKey, JSON.stringify(credentials));
                    }
                    catch (e) {
                        // Ignore
                    }
                    InternalLogger.debug('AWS credentials fetched successfully');
                    return credentials;
                }
                catch (e) {
                    if (retries) {
                        retries--;
                        InternalLogger.warn('AWS credential fetch failed, retrying');
                    }
                    else {
                        InternalLogger.error('AWS credential fetch failed:', e);
                        throw e;
                    }
                }
            }
        };
        const region = config.identityPoolId.split(':')[0];
        this.stsClient = new StsClient({
            fetchRequestHandler: new FetchHttpHandler(),
            region
        });
    }
}
