import { ResourceType } from '../../utils/common-utils';
export const defaultIgnore = (entry) => entry.entryType === 'resource' &&
    (!/^https?:/.test(entry.name) ||
        /^(fetch|xmlhttprequest)$/.test(entry.initiatorType));
export const defaultPerformancePluginConfig = {
    eventLimit: 10,
    ignore: defaultIgnore,
    recordAllTypes: [
        ResourceType.DOCUMENT,
        ResourceType.SCRIPT,
        ResourceType.STYLESHEET,
        ResourceType.FONT
    ],
    sampleTypes: [ResourceType.IMAGE, ResourceType.OTHER],
    reportAllLCP: false,
    reportAllCLS: false,
    reportAllINP: false
};
