import { BasicAuthentication, EnhancedAuthentication, DomEventPlugin, DOM_EVENT_PLUGIN_ID, JsErrorPlugin, JS_ERROR_EVENT_PLUGIN_ID, NavigationPlugin, ResourcePlugin, WebVitalsPlugin, XhrPlugin, FetchPlugin, RRWebPlugin, InternalLogger, createSigningConfig } from '@aws-rum/web-core';
import { Orchestration as SlimOrchestration } from '@aws-rum/web-slim';
import { TelemetryEnum, defaultConfig, defaultCookieAttributes } from './config';
// Re-export config types for public API
export { TelemetryEnum, PageIdFormatEnum, defaultCookieAttributes, defaultConfig } from './config';
/**
 * Full-featured orchestrator extending slim with auth, signing, and
 * the telemetries plugin system.
 */
export class Orchestration extends SlimOrchestration {
    constructor(applicationId, applicationVersion, region, partialConfig = {}) {
        super(applicationId, applicationVersion, region, Object.assign(Object.assign({}, defaultConfig(defaultCookieAttributes())), partialConfig));
        InternalLogger.info(`RUM client initialized for app: ${applicationId}`);
        InternalLogger.info(`Telemetries enabled: ${this.config.telemetries.join(', ') || 'none'}`);
    }
    initDispatch(region, applicationId) {
        const dispatch = super.initDispatch(region, applicationId);
        // Inject signing support
        dispatch.setSigningConfigFactory(createSigningConfig);
        // Inject Cognito credential provider factory
        dispatch.setCognitoCredentialProviderFactory((config, appId, identityPoolId, guestRoleArn) => {
            const authConfig = {
                identityPoolId,
                guestRoleArn,
                cookieAttributes: config.cookieAttributes
            };
            if (identityPoolId && guestRoleArn) {
                return new BasicAuthentication(authConfig, appId)
                    .ChainAnonymousCredentialsProvider;
            }
            return new EnhancedAuthentication(authConfig, appId)
                .ChainAnonymousCredentialsProvider;
        });
        if (this.config.signing && this.config.identityPoolId) {
            dispatch.setCognitoCredentials(this.config.identityPoolId, this.config.guestRoleArn);
        }
        return dispatch;
    }
    initPluginManager(applicationId, applicationVersion) {
        const pluginManager = super.initPluginManager(applicationId, applicationVersion);
        // Add telemetry functor plugins
        const builtinPlugins = this.constructBuiltinPlugins();
        builtinPlugins.forEach((p) => {
            pluginManager.addPlugin(p);
        });
        return pluginManager;
    }
    /**
     * Record an error using the JS error plugin.
     */
    recordError(error) {
        this.pluginManager.record(JS_ERROR_EVENT_PLUGIN_ID, error);
    }
    /**
     * Update DOM plugin to record the (additional) provided DOM events.
     */
    registerDomEvents(events) {
        this.pluginManager.updatePlugin(DOM_EVENT_PLUGIN_ID, events);
    }
    constructBuiltinPlugins() {
        let plugins = [];
        const functor = this.telemetryFunctor();
        this.config.telemetries.forEach((type) => {
            if (typeof type === 'string' && functor[type.toLowerCase()]) {
                plugins = [...plugins, ...functor[type.toLowerCase()]({})];
            }
            else if (Array.isArray(type) &&
                functor[type[0].toLowerCase()]) {
                plugins = [
                    ...plugins,
                    ...functor[type[0].toLowerCase()](type[1])
                ];
            }
        });
        return plugins;
    }
    /**
     * Returns a functor which maps data collection categories to
     * instantiated plugins.
     */
    telemetryFunctor() {
        return {
            [TelemetryEnum.Errors]: (config) => {
                return [new JsErrorPlugin(config)];
            },
            [TelemetryEnum.Performance]: (config) => {
                return [
                    new NavigationPlugin(config),
                    new ResourcePlugin(config),
                    new WebVitalsPlugin(config)
                ];
            },
            [TelemetryEnum.Interaction]: (config) => {
                return [new DomEventPlugin(config)];
            },
            [TelemetryEnum.Http]: (config) => {
                return [new XhrPlugin(config), new FetchPlugin(config)];
            },
            [TelemetryEnum.Replay]: (config) => {
                return [new RRWebPlugin(config)];
            }
        };
    }
}
