import * as shimmer from 'shimmer';
import { InternalPlugin } from './InternalPlugin';
export class MonkeyPatched extends InternalPlugin {
    constructor() {
        super(...arguments);
        this.enable = this.patch.bind(this, true);
        this.disable = this.patch.bind(this, false);
        this.enabled = false;
    }
    patchAll() {
        const wrap = shimmer.wrap.bind(shimmer);
        for (const patch of this.patches) {
            wrap(patch.nodule, patch.name, patch.wrapper());
        }
    }
    unpatchAll() {
        const unwrap = shimmer.unwrap.bind(shimmer);
        for (const patch of this.patches) {
            unwrap(patch.nodule, patch.name);
        }
    }
    patch(shouldPatch = true) {
        if (this.enabled !== shouldPatch) {
            this.enabled = shouldPatch;
            if (shouldPatch) {
                this.patchAll();
            }
            else {
                this.unpatchAll();
            }
        }
    }
}
