import { toHex } from '@smithy/util-hex-encoding';
import { SignatureV4 } from '@smithy/signature-v4';
import { Sha256 } from '@aws-crypto/sha256-js';
const SERVICE = 'rum';
const REQUEST_PRESIGN_ARGS = { expiresIn: 60 };
export const createSigningConfig = (credentials, region) => {
    const awsSigV4 = new SignatureV4({
        applyChecksum: true,
        credentials,
        region,
        service: SERVICE,
        uriEscapePath: true,
        sha256: Sha256
    });
    return {
        sign: async (request) => (await awsSigV4.sign(request)),
        presign: async (request) => (await awsSigV4.presign(request, REQUEST_PRESIGN_ARGS)),
        hashAndEncode: async (payload) => {
            const sha256 = new Sha256();
            sha256.update(payload);
            return toHex(await sha256.digest()).toLowerCase();
        }
    };
};
